def transform(grid):
    g = np.array(grid)
    bg = background(g)
    out = g.copy()
    emit(out, "Start from the input: find objects that enclose a hole of background.")
    H, W = g.shape
    for o in objects(g, bg=bg):
        m = np.zeros((H, W), bool)
        for y, x in o["cells"]:
            m[y, x] = True
        closed = False
        for comp in components(~m):
            if not any(y in (0, H - 1) or x in (0, W - 1) for y, x in comp):
                closed = True
                break
        if closed:
            for y, x in o["cells"]:
                out[y, x] = 3
            emit(out, f"Object at box {o['box']} fully encloses a hole, so it is recoloured to 3.")
    emit(out, "All closed shapes are now 3; open shapes and fragments stay unchanged.")
    return out
